func (this *Deribit) ParseCurrency(rawCurrency any) any {
	var currencyId *string = this.SafeString(rawCurrency, "currency")
	var code *string = this.SafeCurrencyCode(currencyId)
	return this.SafeCurrencyStructure(map[string]any{
		"info":      rawCurrency,
		"code":      code,
		"id":        currencyId,
		"name":      this.SafeString(rawCurrency, "currency_long"),
		"active":    nil,
		"deposit":   nil,
		"withdraw":  nil,
		"type":      "crypto",
		"fee":       this.SafeNumber(rawCurrency, "withdrawal_fee"),
		"precision": nil,
		"limits": map[string]any{
			"amount": map[string]any{
				"min": nil,
				"max": nil,
			},
			"withdraw": map[string]any{
				"min": nil,
				"max": nil,
			},
			"deposit": map[string]any{
				"min": nil,
				"max": nil,
			},
		},
		"networks": nil,
	})
}
func (this *Deribit) CodeFromOptions(methodName any, optionalArgs ...any) any {
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var defaultCode *string = this.SafeString(this.Options, "code", "BTC")
	var options map[string]any = SafeMapTyped(this.Options, methodName)
	var code *string = this.SafeString(options, "code", defaultCode)
	return this.SafeString(params, "code", code)
}

/**
 * @method
 * @name deribit#fetchStatus
 * @description the latest known information on the availability of the exchange API
 * @see https://docs.deribit.com/#public-status
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object} a [status structure]{@link https://docs.ccxt.com/?id=exchange-status-structure}
 */
func (this *Deribit) FetchStatusAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchStatusBody(ch, optionalArgs...)
	return ch
}
func (this *Deribit) fetchStatusBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params

	response := (<-this.PublicGetStatus(params)).Raw
	PanicOnError(response)
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "result": {
	//             "locked": "false" // true, partial, false
	//         },
	//         "usIn": 1650641690226788,
	//         "usOut": 1650641690226836,
	//         "usDiff": 48,
	//         "testnet": false
	//     }
	//
	var result map[string]any = SafeMapTyped(response, "result")
	var locked *string = this.SafeString(result, "locked")
	var updateTime *int64 = this.SafeIntegerProduct(response, "usIn", 0.001, this.Milliseconds())

	ch <- map[string]any{
		"status": func() string {
			if locked != nil && *locked == "false" {
				return "ok"
			}
			return "maintenance"
		}(),
		"updated": updateTime,
		"eta":     nil,
		"url":     nil,
		"info":    response,
	}
	return nil
}

