/**
 * @method
 * @name deribit#fetchMarkets
 * @description retrieves data on all markets for deribit
 * @see https://docs.deribit.com/#public-get_currencies
 * @see https://docs.deribit.com/#public-get_instruments
 * @param {object} [params] extra parameters specific to the exchange API endpoint
 * @returns {object[]} an array of objects representing market data
 */
func (this *Deribit) FetchMarketsAsync(optionalArgs ...any) <-chan any {
	ch := make(chan any, 1)
	go this.fetchMarketsBody(ch, optionalArgs...)
	return ch
}
func (this *Deribit) fetchMarketsBody(ch chan any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	var instrumentsResponses []any = []any{}
	var result []any = []any{}
	var parsedMarkets map[string]any = map[string]any{}
	var fetchAllMarketsparamsFetchAllMarketsVariable []any = this.HandleOptionBoolAndParams(params, "fetchMarkets", "fetchAllMarkets", true)
	var fetchAllMarkets bool = GetValueBool(fetchAllMarketsparamsFetchAllMarketsVariable, 0, false)
	var paramsFetchAllMarkets map[string]any = MapTyped(GetValue(fetchAllMarketsparamsFetchAllMarketsVariable, 1))
	if fetchAllMarkets {

		instrumentsResponse := (<-this.PublicGetGetInstruments(paramsFetchAllMarkets)).Raw
		PanicOnError(instrumentsResponse)
		instrumentsResponses = append(instrumentsResponses, instrumentsResponse)
	} else {

		var currenciesResponse map[string]any = MapTyped(PanicOnError((<-this.PublicGetGetCurrencies(paramsFetchAllMarkets)).Raw))
		//
		//     {
		//         "jsonrpc": "2.0",
		//         "result": [
		//             {
		//                 "withdrawal_priorities": [
		//                     { value: 0.15, name: "very_low" },
		//                     { value: 1.5, name: "very_high" },
		//                 ],
		//                 "withdrawal_fee": 0.0005,
		//                 "min_withdrawal_fee": 0.0005,
		//                 "min_confirmations": 1,
		//                 "fee_precision": 4,
		//                 "currency_long": "Bitcoin",
		//                 "currency": "BTC",
		//                 "coin_type": "BITCOIN"
		//             }
		//         ],
		//         "usIn": 1583761588590479,
		//         "usOut": 1583761588590544,
		//         "usDiff": 65,
		//         "testnet": false
		//     }
		//
		var currenciesResult []any = SafeListTyped(currenciesResponse, "result")
		for i := 0; i < len(currenciesResult); i++ {
			var currencyId *string = this.SafeString(func() any {
				if i >= 0 && i < len(currenciesResult) {
					return DerefScalar(currenciesResult[i])
				}
				return nil
			}(), "currency")
			var request map[string]any = map[string]any{
				"currency": currencyId,
			}

			instrumentsResponse := (<-this.PublicGetGetInstruments(this.Extend(request, paramsFetchAllMarkets))).Raw
			PanicOnError(instrumentsResponse)
			//
			//     {
			//         "jsonrpc":"2.0",
			//         "result":[
			//             {
			//                 "tick_size":0.0005,
			//                 "taker_commission":0.0003,
			//                 "strike":52000.0,
			//                 "settlement_period":"month",
			//                 "settlement_currency":"BTC",
			//                 "quote_currency":"BTC",
			//                 "option_type":"put", // put, call
			//                 "min_trade_amount":0.1,
			//                 "maker_commission":0.0003,
			//                 "kind":"option",
			//                 "is_active":true,
			//                 "instrument_name":"BTC-24JUN22-52000-P",
			//                 "expiration_timestamp":1656057600000,
			//                 "creation_timestamp":1648199543000,
			//                 "counter_currency":"USD",
			//                 "contract_size":1.0,
			//                 "block_trade_commission":0.0003,
			//                 "base_currency":"BTC"
			//             },
			//             {
			//                 "tick_size":0.5,
			//                 "taker_commission":0.0005,
			//                 "settlement_period":"month", // month, week
			//                 "settlement_currency":"BTC",
			//                 "quote_currency":"USD",
			//                 "min_trade_amount":10.0,
			//                 "max_liquidation_commission":0.0075,
			//                 "max_leverage":50,
			//                 "maker_commission":0.0,
			//                 "kind":"future",
			//                 "is_active":true,
			//                 "instrument_name":"BTC-27MAY22",
			//                 "future_type":"reversed",
			//                 "expiration_timestamp":1653638400000,
			//                 "creation_timestamp":1648195209000,
			//                 "counter_currency":"USD",
			//                 "contract_size":10.0,
			//                 "block_trade_commission":0.0001,
			//                 "base_currency":"BTC"
			//             },
			//             {
			//                 "tick_size":0.5,
			//                 "taker_commission":0.0005,
			//                 "settlement_period":"perpetual",
			//                 "settlement_currency":"BTC",
			//                 "quote_currency":"USD",
			//                 "min_trade_amount":10.0,
			//                 "max_liquidation_commission":0.0075,
			//                 "max_leverage":50,
			//                 "maker_commission":0.0,
			//                 "kind":"future",
			//                 "is_active":true,
			//                 "instrument_name":"BTC-PERPETUAL",
			//                 "future_type":"reversed",
			//                 "expiration_timestamp":32503708800000,
			//                 "creation_timestamp":1534242287000,
			//                 "counter_currency":"USD",
			//                 "contract_size":10.0,
			//                 "block_trade_commission":0.0001,
			//                 "base_currency":"BTC"
			//             },
			//         ],
			//         "usIn":1648691472831791,
			//         "usOut":1648691472831896,
			//         "usDiff":105,
			//         "testnet":false
			//     }
			//
			instrumentsResponses = append(instrumentsResponses, instrumentsResponse)
		}
	}
	for i := 0; i < len(instrumentsResponses); i++ {
		var instrumentsResult []any = SafeListTyped(func() any {
			if i >= 0 && i < len(instrumentsResponses) {
				return DerefScalar(instrumentsResponses[i])
			}
			return nil
		}(), "result")
		for k := 0; k < len(instrumentsResult); k++ {
			var market any = func() any {
				if k >= 0 && k < len(instrumentsResult) {
					return DerefScalar(instrumentsResult[k])
				}
				return nil
			}()
			var kind *string = this.SafeString(market, "kind")
			var isSpot bool = (kind != nil && *kind == "spot")
			var id *string = this.SafeString(market, "instrument_name")
			var baseId *string = this.SafeString(market, "base_currency")
			var quoteId *string = this.SafeString(market, "counter_currency")
			var settleId *string = this.SafeString(market, "settlement_currency")
			var base *string = this.SafeCurrencyCode(baseId)
			var quote *string = this.SafeCurrencyCode(quoteId)
			if (base == nil) || (quote == nil) {
				continue
			}
			var settle *string = this.SafeCurrencyCode(settleId)
			var settlementPeriod *string = this.SafeString(market, "settlement_period")
			var swap bool = (settlementPeriod != nil && *settlementPeriod == "perpetual")
			if kind == nil {
				panic(ExchangeError(this.Id + " method() missing kind"))
			}
			var future bool = !swap && (func() int {
				if kind == nil {
					return -1
				}
				return strings.Index(*kind, "future")
			}() >= 0)
			if kind == nil {
				panic(ExchangeError(this.Id + " method() missing kind"))
			}
			var option bool = (func() int {
				if kind == nil {
					return -1
				}
				return strings.Index(*kind, "option")
			}() >= 0)
			if kind == nil {
				panic(ExchangeError(this.Id + " method() missing kind"))
			}
			var isComboMarket bool = (func() int {
				if kind == nil {
					return -1
				}
				return strings.Index(*kind, "combo")
			}() >= 0)
			var expiry *int64 = this.SafeInteger(market, "expiration_timestamp")
			var strike *float64 = nil
			var optionType *string = nil
			var symbol any = id
			var typeVar string = "swap"
			if future {
				typeVar = "future"
			} else if option {
				typeVar = "option"
			} else if isSpot {
				typeVar = "spot"
			}
			var inverse any = nil
			var linear any = nil
			if isSpot {
				symbol = *base + "/" + *quote
			} else if !isComboMarket {
				symbol = Add(*base+"/"+*quote+":", settle)
				if option || future {
					symbol = Add(Add(symbol, "-"), this.Yymmdd(expiry, ""))
					if option {
						strike = this.SafeNumber(market, "strike")
						optionType = this.SafeString(market, "option_type")
						var letter string = func() string {
							if optionType != nil && *optionType == "call" {
								return "C"
							}
							return "P"
						}()
						symbol = Add(Add(Add(Add(symbol, "-"), this.NumberToString(strike)), "-"), letter)
					}
				}
				inverse = (quote != settle && (quote == nil || settle == nil || *quote != *settle))
				linear = (settle == quote || (settle != nil && quote != nil && *settle == *quote))
			}
			var parsedMarketValue *bool = this.SafeBool(parsedMarkets, symbol)
			if parsedMarketValue != nil {
				continue
			}
			if !IsEqual(symbol, nil) {
				AddElementToObject(parsedMarkets, symbol, true)
			}
			var minTradeAmount *float64 = this.SafeNumber(market, "min_trade_amount")
			var tickSize *float64 = this.SafeNumber(market, "tick_size")
			result = append(result, map[string]any{
				"id":             id,
				"symbol":         symbol,
				"base":           base,
				"quote":          quote,
				"settle":         settle,
				"baseId":         baseId,
				"quoteId":        quoteId,
				"settleId":       settleId,
				"type":           typeVar,
				"spot":           isSpot,
				"margin":         false,
				"swap":           swap,
				"future":         future,
				"option":         option,
				"active":         this.SafeBool(market, "is_active"),
				"contract":       !isSpot,
				"linear":         linear,
				"inverse":        inverse,
				"taker":          this.SafeNumber(market, "taker_commission"),
				"maker":          this.SafeNumber(market, "maker_commission"),
				"contractSize":   this.SafeNumber(market, "contract_size"),
				"expiry":         expiry,
				"expiryDatetime": this.Iso8601(expiry),
				"strike":         strike,
				"optionType":     optionType,
				"precision": map[string]any{
					"amount": minTradeAmount,
					"price":  tickSize,
				},
				"limits": map[string]any{
					"leverage": map[string]any{
						"min": nil,
						"max": nil,
					},
					"amount": map[string]any{
						"min": minTradeAmount,
						"max": nil,
					},
					"price": map[string]any{
						"min": tickSize,
						"max": nil,
					},
					"cost": map[string]any{
						"min": nil,
						"max": nil,
					},
				},
				"created": this.SafeInteger(market, "creation_timestamp"),
				"info":    market,
			})
		}
	}

	ch <- result
	return nil
}
func (this *Deribit) ParseBalance(balance any) any {
	var result map[string]any = map[string]any{
		"info": balance,
	}
	var summaries []any = []any{}
	if InOp(balance, "summaries") {
		summaries = ArrayTyped(this.SafeList(balance, "summaries", []any{}))
	} else {
		summaries = []any{balance}
	}
	for i := 0; i < len(summaries); i++ {
		var data map[string]any = SafeMapTyped(summaries, i)
		var currencyId *string = this.SafeString(data, "currency")
		var currencyCode *string = this.SafeCurrencyCode(currencyId)
		var account map[string]any = this.Account()
		account["free"] = this.SafeString(data, "available_funds")
		account["used"] = this.SafeString(data, "maintenance_margin")
		account["total"] = this.SafeString(data, "equity")
		if currencyCode != nil {
			result[*currencyCode] = account
		}
	}
	return this.SafeBalance(result)
}

