func (this *Deribit) transferBody(ch chan any, code any, amount any, fromAccount any, toAccount any, optionalArgs ...any) any {
	defer close(ch)
	defer ReturnPanicError(ch)
	var params map[string]any = GetArgMap(optionalArgs, 0, map[string]any{})
	_ = params
	if this.Markets == nil {

		PanicOnError((<-this.LoadMarketsAsync()))
	}
	var currency map[string]any = this.Currency(code)
	var request map[string]any = map[string]any{
		"amount":      amount,
		"currency":    currency["id"],
		"destination": toAccount,
	}
	var method *string = this.SafeString(params, "method")
	var paramsOmitted map[string]any = MapTyped(this.Omit(params, "method"))
	if method == nil {
		var transferOptions map[string]any = SafeMapTyped(this.Options, "transfer")
		method = this.SafeString(transferOptions, "method", "privateGetSubmitTransferToSubaccount")
	}
	var response map[string]any = nil
	if method != nil && *method == "privateGetSubmitTransferToUser" {

		response = MapTyped(PanicOnError((<-this.PrivateGetSubmitTransferToUser(this.Extend(request, paramsOmitted))).Raw))
	} else {

		response = MapTyped(PanicOnError((<-this.PrivateGetSubmitTransferToSubaccount(this.Extend(request, paramsOmitted))).Raw))
	}
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "id": 9421,
	//         "result": {
	//             "updated_timestamp": 1550232862350,
	//             "type": "user",
	//             "state": "prepared",
	//             "other_side": "0x4aa0753d798d668056920094d65321a8e8913e26",
	//             "id": 3,
	//             "direction": "payment",
	//             "currency": "ETH",
	//             "created_timestamp": 1550232862350,
	//             "amount": 13.456
	//         }
	//     }
	//
	var result map[string]any = MapTyped(this.SafeDict(response, "result", map[string]any{}))

	ch <- this.ParseTransfer(result, currency)
	return nil
}
func (this *Deribit) ParseTransfer(transfer any, optionalArgs ...any) any {
	//
	//     {
	//         "updated_timestamp": 1550232862350,
	//         "type": "user",
	//         "state": "prepared",
	//         "other_side": "0x4aa0753d798d668056920094d65321a8e8913e26",
	//         "id": 3,
	//         "direction": "payment",
	//         "currency": "ETH",
	//         "created_timestamp": 1550232862350,
	//         "amount": 13.456
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var timestamp *int64 = this.SafeInteger(transfer, "created_timestamp")
	var status *string = this.SafeString(transfer, "state")
	var account *string = this.SafeString(transfer, "other_side")
	var direction *string = this.SafeString(transfer, "direction")
	var currencyId *string = this.SafeString(transfer, "currency")
	return map[string]any{
		"info":     transfer,
		"id":       this.SafeString(transfer, "id"),
		"status":   this.ParseTransferStatus(status),
		"amount":   this.SafeNumber(transfer, "amount"),
		"currency": this.SafeCurrencyCode(currencyId, currency),
		"fromAccount": func() any {
			if direction == nil || *direction != "payment" {
				return account
			}
			return nil
		}(),
		"toAccount": func() any {
			if direction != nil && *direction == "payment" {
				return account
			}
			return nil
		}(),
		"timestamp": timestamp,
		"datetime":  this.Iso8601(timestamp),
	}
}
func (this *Deribit) ParseTransferStatus(status *string) *string {
	var statuses map[string]any = map[string]any{
		"prepared":          "pending",
		"confirmed":         "ok",
		"cancelled":         "cancelled",
		"waiting_for_admin": "pending",
	}
	return this.SafeString(statuses, status, status)
}

