func (this *Deribit) ParseGreeks(greeks any, optionalArgs ...any) any {
	//
	//     {
	//         "estimated_delivery_price": 36552.72,
	//         "best_bid_amount": 0.2,
	//         "best_ask_amount": 9.1,
	//         "interest_rate": 0.0,
	//         "best_bid_price": 0.214,
	//         "best_ask_price": 0.219,
	//         "open_interest": 368.8,
	//         "settlement_price": 0.22103022,
	//         "last_price": 0.215,
	//         "bid_iv": 60.51,
	//         "ask_iv": 61.88,
	//         "mark_iv": 61.27,
	//         "underlying_index": "BTC-27SEP24",
	//         "underlying_price": 38992.71,
	//         "min_price": 0.1515,
	//         "max_price": 0.326,
	//         "mark_price": 0.2168,
	//         "instrument_name": "BTC-27SEP24-40000-C",
	//         "index_price": 36552.72,
	//         "greeks": {
	//             "rho": 130.63998,
	//             "theta": -13.48784,
	//             "vega": 141.90146,
	//             "gamma": 0.00002,
	//             "delta": 0.59621
	//         },
	//         "stats": {
	//             "volume_usd": 100453.9,
	//             "volume": 12.0,
	//             "price_change": -2.2727,
	//             "low": 0.2065,
	//             "high": 0.238
	//         },
	//         "state": "open",
	//         "timestamp": 1699578548021
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger(greeks, "timestamp")
	var marketId *string = this.SafeString(greeks, "instrument_name")
	var symbol *string = this.SafeSymbol(marketId, market)
	var stats map[string]any = SafeMapTyped(greeks, "greeks")
	return map[string]any{
		"symbol":                symbol,
		"timestamp":             timestamp,
		"datetime":              this.Iso8601(timestamp),
		"delta":                 this.SafeNumber(stats, "delta"),
		"gamma":                 this.SafeNumber(stats, "gamma"),
		"theta":                 this.SafeNumber(stats, "theta"),
		"vega":                  this.SafeNumber(stats, "vega"),
		"rho":                   this.SafeNumber(stats, "rho"),
		"bidSize":               this.SafeNumber(greeks, "best_bid_amount"),
		"askSize":               this.SafeNumber(greeks, "best_ask_amount"),
		"bidImpliedVolatility":  this.SafeNumber(greeks, "bid_iv"),
		"askImpliedVolatility":  this.SafeNumber(greeks, "ask_iv"),
		"markImpliedVolatility": this.SafeNumber(greeks, "mark_iv"),
		"bidPrice":              this.SafeNumber(greeks, "best_bid_price"),
		"askPrice":              this.SafeNumber(greeks, "best_ask_price"),
		"markPrice":             this.SafeNumber(greeks, "mark_price"),
		"lastPrice":             this.SafeNumber(greeks, "last_price"),
		"underlyingPrice":       this.SafeNumber(greeks, "underlying_price"),
		"info":                  greeks,
	}
}

