func (this *Deribit) ParseOption(chain any, optionalArgs ...any) any {
	//
	//     {
	//         "mid_price": 0.04025,
	//         "volume_usd": 11045.12,
	//         "quote_currency": "BTC",
	//         "estimated_delivery_price": 65444.72,
	//         "creation_timestamp": 1711100949273,
	//         "base_currency": "BTC",
	//         "underlying_index": "BTC-27DEC24",
	//         "underlying_price": 73742.14,
	//         "volume": 4.0,
	//         "interest_rate": 0.0,
	//         "price_change": -6.9767,
	//         "open_interest": 274.2,
	//         "ask_price": 0.042,
	//         "bid_price": 0.0385,
	//         "instrument_name": "BTC-27DEC24-240000-C",
	//         "mark_price": 0.04007735,
	//         "last": 0.04,
	//         "low": 0.04,
	//         "high": 0.043
	//     }
	//
	var currency map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = currency
	var market map[string]any = GetArgMap(optionalArgs, 1, nil)
	_ = market
	var marketId *string = this.SafeString(chain, "instrument_name")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var currencyId *string = this.SafeString(chain, "base_currency")
	var code *string = this.SafeCurrencyCode(currencyId, currency)
	var timestamp *int64 = this.SafeInteger(chain, "timestamp")
	return map[string]any{
		"info":              chain,
		"currency":          code,
		"symbol":            marketResolved["symbol"],
		"timestamp":         timestamp,
		"datetime":          this.Iso8601(timestamp),
		"impliedVolatility": nil,
		"openInterest":      this.SafeNumber(chain, "open_interest"),
		"bidPrice":          this.SafeNumber(chain, "bid_price"),
		"askPrice":          this.SafeNumber(chain, "ask_price"),
		"midPrice":          this.SafeNumber(chain, "mid_price"),
		"markPrice":         this.SafeNumber(chain, "mark_price"),
		"lastPrice":         this.SafeNumber(chain, "last"),
		"underlyingPrice":   this.SafeNumber(chain, "underlying_price"),
		"change":            nil,
		"percentage":        this.SafeNumber(chain, "price_change"),
		"baseVolume":        this.SafeNumber(chain, "volume"),
		"quoteVolume":       this.SafeNumber(chain, "volume_usd"),
	}
}

