func (this *Deribit) ParseOpenInterest(interest any, optionalArgs ...any) any {
	//
	//     {
	//         "high": 93099.5,
	//         "low": 81773.0,
	//         "last": 87197.0,
	//         "instrument_name": "BTC-PERPETUAL",
	//         "bid_price": 87083.0,
	//         "ask_price": 87149.5,
	//         "open_interest": 9978911260,
	//         "mark_price": 87102.01,
	//         "creation_timestamp": 1763674177068,
	//         "price_change": -3.2032,
	//         "volume": 7377.18657991,
	//         "estimated_delivery_price": 87047.2,
	//         "base_currency": "BTC",
	//         "quote_currency": "USD",
	//         "volume_usd": 661040250.0,
	//         "volume_notional": 661040250.0,
	//         "current_funding": 1.2966e-4,
	//         "funding_8h": -8.1069e-4,
	//         "mid_price": 87116.25
	//     }
	//
	var market map[string]any = GetArgMap(optionalArgs, 0, nil)
	_ = market
	var timestamp *int64 = this.SafeInteger(interest, "creation_timestamp")
	var marketId *string = this.SafeString(interest, "instrument_name")
	var marketResolved map[string]any = this.SafeMarket(marketId, market)
	var openInterest *float64 = this.SafeNumber(interest, "open_interest")
	var openInterestAmount *float64 = nil
	var openInterestValue *float64 = nil
	if (marketResolved["option"] == true) || ((marketResolved["future"] == true) && (marketResolved["linear"] == true)) {
		openInterestAmount = openInterest
	} else {
		openInterestValue = openInterest
	}
	return this.SafeOpenInterest(map[string]any{
		"symbol":             this.SafeSymbol(marketId, marketResolved),
		"openInterestAmount": openInterestAmount,
		"openInterestValue":  openInterestValue,
		"timestamp":          timestamp,
		"datetime":           this.Iso8601(timestamp),
		"info":               interest,
	}, marketResolved)
}
func (this *Deribit) Nonce() any {
	return this.Milliseconds()
}
func (this *Deribit) Sign(path string, optionalArgs ...any) any {
	api := GetArg(optionalArgs, 0, "public")
	_ = api
	var method string = GetArgString(optionalArgs, 1, "GET")
	_ = method
	params := GetArg(optionalArgs, 2, map[string]any{})
	_ = params
	headers := GetArg(optionalArgs, 3, nil)
	_ = headers
	var body *string = GetArgStringPtr(optionalArgs, 4, nil)
	_ = body
	var request any = Add(Add(Add("/"+"api/"+this.Version+"/", api), "/"), path)
	if IsEqual(api, "public") {
		if len(ObjectKeys(params)) > 0 {
			request = Add(request, "?"+this.Urlencode(params))
		}
	}
	if IsEqual(api, "private") {
		this.CheckRequiredCredentials()
		var nonce string = ToString(this.Nonce())
		var timestamp string = strconv.FormatInt(this.Milliseconds(), 10)
		var requestBody string = ""
		if len(ObjectKeys(params)) > 0 {
			request = Add(request, "?"+this.Urlencode(params))
		}
		var requestData any = Add(Add(Add(Add(method+"\n", request), "\n"), requestBody), "\n") // eslint-disable-line quotes
		var auth *string = SafeStringPtr(Add(timestamp+"\n"+nonce+"\n", requestData))           // eslint-disable-line quotes
		var signature string = this.Hmac(this.Encode(auth), this.Encode(this.Secret), sha256)
		var signedHeaders map[string]any = map[string]any{
			"Authorization": Add(Add(Add(Add(Add(Add(Add(Add("deri-hmac-sha256 id=", this.ApiKey), ",ts="), timestamp), ",sig="), signature), ","), "nonce="), nonce),
		}
		var baseApiUrl *string = this.SafeString(GetValue(this.Urls, "api"), "rest")
		if baseApiUrl == nil {
			panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
		}
		var signedUrl *string = SafeStringPtr(Add(baseApiUrl, request))
		return map[string]any{
			"url":     signedUrl,
			"method":  method,
			"body":    body,
			"headers": signedHeaders,
		}
	}
	var apiUrl *string = this.SafeString(GetValue(this.Urls, "api"), "rest")
	if apiUrl == nil {
		panic(ExchangeError(this.Id + " sign() has no API URL for this endpoint"))
	}
	var url *string = SafeStringPtr(Add(apiUrl, request))
	return map[string]any{
		"url":     url,
		"method":  method,
		"body":    body,
		"headers": headers,
	}
}
func (this *Deribit) HandleErrors(httpCode any, reason any, url any, method any, headers any, body any, response any, requestHeaders any, requestBody any) any {
	if (IsEqual(response, nil)) || (IsEqual(response, nil)) {
		return nil // fallback to default error handler
	}
	//
	//     {
	//         "jsonrpc": "2.0",
	//         "error": {
	//             "message": "Invalid params",
	//             "data": { reason: "invalid currency", param: "currency" },
	//             "code": -32602
	//         },
	//         "testnet": false,
	//         "usIn": 1583763842150374,
	//         "usOut": 1583763842150410,
	//         "usDiff": 36
	//     }
	//
	var error map[string]any = SafeMapTyped(response, "error")
	if error != nil {
		var errorCode *string = this.SafeString(error, "code")
		var feedback *string = SafeStringPtr(Add(this.Id+" ", body))
		this.ThrowExactlyMatchedException(this.Exceptions, errorCode, feedback)
		panic(ExchangeError(feedback))
	}
	return nil
}

func NewDeribit(userConfig map[string]any) *Deribit {
	p := newDeribit()
	p.Init(userConfig)
	return p
}

func (this *Deribit) Init(userConfig map[string]any) {
	this.Exchange = Exchange{}
	this.Exchange.DerivedExchange = this
	this.Exchange.InitParent(userConfig, this.Describe().(map[string]any), this)
	this.exchangeTyped = NewExchangeTyped(&this.Exchange)
}

